mapper.select:
SELECT sp.* FROM eb_store_pink AS sp left join eb_store_product pro on pro.id = sp.pid left join eb_user u on u.uid = sp.uid
sp.status = #{status}
and pro.store_name like CONCAT('%',#{productName},'%')
and sp.add_time between #{startTime} and #{endTime}
and ( u.uid like CONCAT('%',#{keywords},'%') or u.nickname like CONCAT('%',#{keywords},'%') or u.phone like CONCAT('%',#{keywords},'%') )
and u.uid = #{uid}
and u.nickname like CONCAT('%',#{nickname},'%')
and u.phone like CONCAT('%',#{phone},'%')
ORDER BY sp.id desc

SELECT count(*) FROM eb_store_pink AS sp left join eb_store_product pro on pro.id = sp.pid left join eb_user u on u.uid = sp.uid where sp.status = #{status}
and pro.store_name like CONCAT('%',#{productName},'%')
and sp.add_time between #{startTime} and #{endTime}
and ( u.uid like CONCAT('%',#{keywords},'%') or u.nickname like CONCAT('%',#{keywords},'%') or u.phone like CONCAT('%',#{keywords},'%') )
and u.uid = #{uid}
and u.nickname like CONCAT('%',#{nickname},'%')
and u.phone like CONCAT('%',#{phone},'%')
ORDER BY sp.id desc
